// SPDX-License-Identifier: MIT
pragma solidity ^0.8.0;

contract Counter {
    uint256 public count;
    int256 public delta;

    function inc(uint256 n) public {
        count += n;
        delta += int256(n);
    }

    function dec(uint256 n) public {
        require(n <= count);
        count -= n;
        delta -= int256(n);
    }
}

contracts/TopDonors.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

contract TopDonors {
    struct Entry {
        address donor;
        uint256 amount;
    }

    Entry[] public board;
    mapping(address => uint256) public donations;
    uint256 public totalDonated;
    address public topDonor;
    uint256 public topAmount;

    function donate() external payable {
        require(msg.value > 0, "Donation must be > 0");

        board.push(
            Entry({
                donor: msg.sender,
                amount: msg.value
            })
        );

        donations[msg.sender] += msg.value;
        totalDonated += msg.value;

        // 더 크면 1위 교체
        if (donations[msg.sender] > topAmount) {
            topDonor = msg.sender;
            topAmount = donations[msg.sender];
        }
    }

    function count() external view returns (uint256) {
        return board.length;
    }
}

contracts/SimpleDonation.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

contract SimpleDonation {
    address payable public beneficiary;
    mapping(address => uint256) public donations;

    constructor(address payable initialBeneficiary) {
        require(initialBeneficiary != address(0));
        beneficiary = initialBeneficiary;
    }

    function donate() external payable {
        donations[msg.sender] += msg.value;
    }

    function withdraw() external {
        require(msg.sender == beneficiary);

        uint256 balance = address(this).balance;
        require(balance > 0);

        (bool success, ) =
            beneficiary.call{value: balance}("");

        require(success, "Withdrawal failed");
    }
}

contracts/PerUserBudget.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.0;

contract PerUserBudget {
    struct Allowance {
        uint256 cap;
        uint256 spent;
    }

    mapping(address => Allowance) public limits;

    function setCap(uint256 capValue) external {
        limits[msg.sender].cap = capValue;
    }

    function spend(uint256 amount) external {
        Allowance storage userAllowance =
            limits[msg.sender];

        require(
            userAllowance.spent + amount <= userAllowance.cap
        );

        userAllowance.spent += amount;
    }

    function remaining(
        address account
    ) external view returns (uint256) {
        return limits[account].cap - limits[account].spent;
    }
}

contracts/DonorBook.sol.content:
pragma solidity ^0.8.0;

contract DonorBook {
    mapping(address => uint256) public donations;
    uint256 public totalDonated;

    function donate() external payable {
        require(msg.value > 0, "empty");

        donations[msg.sender] += msg.value;
        totalDonated += msg.value;
    }

    function refund(uint256 amount) external {
        require(amount == donations[msg.sender]);

        donations[msg.sender] -= amount;

        (bool success, ) =
            payable(msg.sender).call{value: amount}("");

        require(success, "Refund failed");
    }
}

contracts/DonationTracker.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.0;

contract DonationTracker {
    struct Donation {
        address donor;
        uint256 amount;
        uint64 timestamp;
    }

    uint256 public totalDonated;
    mapping(address => uint256) public donations;
    Donation[] public history;

    function donate() external payable {
        totalDonated += msg.value;
        donations[msg.sender] += msg.value;

        history.push(
            Donation({
                donor: msg.sender,
                amount: msg.value,
                timestamp: uint64(block.timestamp)
            })
        );
    }
}

contracts/CampaignRoster.sol.content:
pragma solidity ^0.8.0;

contract CampaignRoster {
    uint[] public campaignIds;

    function open(uint campaignId) external {
        campaignIds.push(campaignId);
    }

    function closeLast() external {
        require(campaignIds.length > 0);
        campaignIds.pop();
    }

    function swapRemove(uint index) external {
        campaignIds[index] =
            campaignIds[campaignIds.length - 1];

        campaignIds.pop();
    }
}

contracts/CampaignRegistry.sol.content:
pragma solidity ^0.8.0;

enum Category { EDU, HEALTH, ENV, ART }

contract CampaignRegistry {
    bytes32 public code;
    Category public category;
    uint public totalDonated;

    constructor(bytes32 campaignCode, Category categoryChoice) {
        code = campaignCode;
        category = categoryChoice;
    }

    function isHealth() external view returns (bool) {
        return category == Category.HEALTH;
    }
}

contracts/CampaignBoard.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.0;

contract CampaignBoard {
    struct Campaign {
        address owner;
        string title;
        uint256 goal;
    }

    mapping(uint256 => Campaign) private boards;
    mapping(uint256 => uint256) public raised;
    uint256[] public campaignIds;

    function create(
        string calldata titleParam,
        uint256 goalAmount
    ) external {
        uint256 campaignId = campaignIds.length;

        boards[campaignId] =
            Campaign(msg.sender, titleParam, goalAmount);

        campaignIds.push(campaignId);
    }

    function donate(uint256 campaignId) external payable {
        raised[campaignId] += msg.value;
    }
}
